    story_philosophy_desc: "<p>Đất vốn bình dị, nằm sâu trong lòng quê hương, tưởng như vô tri và thô mộc. Nhưng qua đôi bàn tay của người nghệ nhân, đất được nhào nặn, tạo hình và thổi vào đó một dáng hình, một công năng, một vẻ đẹp riêng. Từ một nắm đất nguyên sơ, có thể trở thành một chiếc bình, một chiếc đĩa, một món đồ trang trí hay một vật dụng hiện diện trong đời sống mỗi ngày.</p><p>Điều khiến tôi yêu gốm không chỉ nằm ở vẻ đẹp của nó, mà ở hành trình biến đổi ấy — từ đất thành hình, từ bàn tay thành giá trị, từ một vật vô tri thành một món đồ có thể lưu giữ cảm xúc và ký ức.</p><blockquote class=\"story-inline-quote\">“Với tôi, một món quà bằng gốm không đơn thuần là một vật phẩm để trao tặng. Đó là một món quà mang theo dấu vết của đất, của bàn tay người làm, của thời gian và của người trao gửi.”</blockquote><p>Một món quà từ nguồn cội — để lưu dấu một khoảnh khắc, một tình cảm, một câu chuyện.</p><p>Và có lẽ, đó cũng là điều tôi muốn HEDY ATELIER kể lại qua từng sản phẩm: những giá trị mộc mạc của đất, được nâng niu bằng đôi bàn tay con người, để trở thành những món đồ đẹp đẽ và có ý nghĩa trong đời sống.</p>",
