        "Gói ghém chiếc tách gốm mộc, đĩa nhỏ và nhành khuynh diệp sấy khô trong hộp quà trang nhã.": "Wrapping a rustic ceramic cup, a small plate, and a dried eucalyptus branch in an elegant gift box.",
        "Làn khói trầm thoát nhẹ qua khe nắp gốm đục lỗ tỉ mỉ, thanh lọc năng lượng cho gian phòng.": "Incense smoke gently escapes through the meticulously pierced ceramic lid, purifying the room's energy.",
        "Đường nét bất đối xứng gợi vẻ đẹp thô mộc của đá núi, ôm ấp nhành hoa khô hay cành lá xanh.": "Asymmetrical lines evoke the raw beauty of mountain rocks, embracing dried flowers or green foliage.",
        "Tô canh lớn": "Large soup bowl",
