    // story.html
    story_page_title: "HEDY ATELIER's Mission — HEDY ATELIER",
    story_hero_title: "HEDY ATELIER's Mission",
    story_philosophy_index: "01 — Origins & Mission",
    story_philosophy_title: "[html]From native clay,<br /><em>to a meaningful gift.</em>",
    story_philosophy_desc: "<p>Clay is inherently simple, lying deep within the homeland, seemingly lifeless and rustic. But through the artisan's hands, clay is kneaded, shaped, and breathed into it a form, a function, a unique beauty. From a raw handful of clay, it can become a vase, a plate, a decorative item, or an everyday object in life.</p><p>What makes me love ceramics is not just its beauty, but that journey of transformation — from clay to form, from hands to value, from a lifeless object to an item that can hold emotions and memories.</p><blockquote class=\"story-inline-quote\">“To me, a ceramic gift is not merely an item to give. It is a gift that carries the traces of clay, of the maker's hands, of time, and of the giver.”</blockquote><p>A gift from the origins — to capture a moment, an emotion, a story.</p><p>And perhaps, that is also what I want HEDY ATELIER to retell through each product: the rustic values of clay, cherished by human hands, to become beautiful and meaningful items in life.</p>",
    story_philosophy_caption: "Traces of clay and the maker's hand in each product",
    story_craft_index: "02 — Craftsmanship",
    story_craft_title: "[html]The art of<br /><em>time & patience.</em>",
    story_craft_step1_title: "01. Clay Selection",
    story_craft_step1_desc: "Starting with raw clay, carefully selected to ensure the most natural durability and color after firing.",
    story_craft_step2_title: "02. Hand Shaping",
    story_craft_step2_desc: "Each piece carries the unique mark of the artisan's hands. No two items are exactly alike.",
    story_craft_step3_title: "03. Fire Finishing",
    story_craft_step3_desc: "Just as a person grows through challenges, the harsh fire of the kiln tempers the clay into a resilient body, creating unique veins and spots — a true testament to handcrafted art.",
    story_materials_index: "03 — Materials",
    story_materials_title: "[html]Celebrating<br /><em>imperfection.</em>",
    story_materials_desc: "We call it Wabi-Sabi. Slight glaze crazing, color variations, or organic iron spots are not flaws, but the unique story of each product. Every line celebrates the original beauty of nature.",
    story_values_index: "04 — Commitment",
    story_values_title: "[html]Core values<br /><em>at HEDY ATELIER.</em>",
    story_values_1_title: "Dedication",
    story_values_1_desc: "Every step, from kneading clay and shaping the core to glazing, is done with the utmost care, carrying the full heart of the maker.",
    story_values_2_title: "Timelessness",
    story_values_2_desc: "Minimalist design that does not follow fleeting trends, ensuring each product retains its value over years of use.",
    story_values_3_title: "Sustainability",
    story_values_3_desc: "Cherishing natural materials, optimizing production processes, and using eco-friendly packaging to minimize environmental impact.",
    story_next_eyebrow: "Continue with what you need",
