    contact_policy_2_desc: "Support returns within 7 days for ready-made products with manufacturer defects. Custom products will comply with initial agreements.",
    contact_policy_3_title: "Clear Origin",
    contact_policy_3_desc: "The studio meets the standards of Bat Trang traditional craft village. Full VAT invoices and factory certificates provided for corporate clients.",
    contact_faq_title: "Frequently Asked Questions",
    contact_faq_1_q: "How long does delivery take?",
    contact_faq_1_a: "For in-stock items, delivery in inner Hanoi takes 1-2 days, other provinces 3-5 working days.",
    contact_faq_2_q: "Does HEDY accept large corporate gift orders?",
    contact_faq_2_a: "Yes. HEDY specializes in providing ceramic gift solutions with logo printing and custom boxes for businesses. Please select \"Cooperation & Wholesale\" in the form above for consultation.",
    contact_faq_3_q: "How to order a completely new ceramic design?",
    contact_faq_3_a: "Please prepare your idea, quantity, desired timeline, and select \"Custom Order\". We will contact you to draw sketches and quote the detailed new mold creation process.",
    
