    "[html]Thông tin đã nhập<br /><em>vẫn được lưu giữ.</em>": "Entered information<br /><em>is still kept.</em>",
    "Giỏ hàng và thông tin nhận hàng của bạn không bị mất. Bạn có thể quay lại và hoàn tất đặt hàng bất kỳ lúc nào.": "Your bag and shipping info are not lost. You can return and complete the order at any time.",
    "Chính sách mua hàng →": "Purchase Policy →",
    "Đã nhận yêu cầu vận chuyển chuyên biệt": "Specialized shipping request received",
    "Đơn hàng đã được tiếp nhận": "Order received",
    "Đang chờ đối chiếu chuyển khoản": "Awaiting transfer reconciliation",
    "Đơn hàng đã được ghi nhận": "Order has been recorded",
    "Đã tiếp nhận đơn hàng (COD)": "Order received (COD)",
    "Phí giao đang chờ xác nhận": "Shipping fee awaiting confirmation",
    "Đã tiếp nhận đơn · Phương thức thanh toán đang xét duyệt": "Order received · Payment method pending review",
    "Đã báo chuyển khoản · Chờ đối soát": "Transfer reported · Awaiting reconciliation",
    "Đang chờ chuyển khoản · Hạn 24 giờ": "Awaiting transfer · 24-hour limit",
    "Đã nhận đơn · thanh toán khi nhận hàng": "Order received · pay on delivery",
    "Kiện gốm của bạn yêu cầu tuyến vận chuyển chuyên biệt. Chuyên viên HEDY sẽ sớm liên hệ báo cước an toàn đến địa chỉ của bạn.": "Your ceramic package requires a specialized shipping route. A HEDY specialist will contact you soon with a safe shipping quote.",
    "Cảm ơn bạn đã đặt hàng tại HEDY ATELIER. Chuyên viên sẽ liên hệ qua điện thoại để xác nhận đơn và tư vấn thanh toán trước khi giao hàng.": "Thank you for ordering at HEDY ATELIER. A specialist will call to confirm your order and advise on payment before shipping.",
    "HEDY đã ghi nhận thông báo chuyển khoản của bạn và đang kiểm tra đối soát số dư trên tài khoản ngân hàng.": "HEDY has acknowledged your transfer notification and is reconciling the balance on our bank account.",
    "Cảm ơn bạn đã lựa chọn HEDY ATELIER. Vui lòng chuyển khoản theo thông tin bên dưới để HEDY tiến hành chuẩn bị kiện gốm chu đáo.": "Thank you for choosing HEDY ATELIER. Please transfer according to the details below so HEDY can prepare your ceramic package carefully.",
    "Số tiền thanh toán khi nhận hàng là": "Amount to pay upon delivery is",
    "HEDY sẽ đóng gói cẩn trọng và giao tận tay bạn.": "HEDY will pack carefully and hand-deliver to you.",
    "HEDY đang đối soát giao dịch và sẽ xác nhận thanh toán ngay khi tiền vào tài khoản.": "HEDY is reconciling the transaction and will confirm payment as soon as funds are received.",
    "Vui lòng hoàn tất chuyển khoản theo thông tin bên dưới để HEDY chuẩn bị đơn.": "Please complete the bank transfer according to the details below so HEDY can prepare your order.",
    "Thông tin đơn hàng đã được ghi nhận.": "Order information has been recorded.",
    "Bước tiếp theo": "Next Steps",
    "[html]Chờ phí giao,<br /><em>chưa thanh toán.</em>": "Awaiting shipping fee,<br /><em>unpaid.</em>",
    "HEDY cần kiểm tra kích thước kiện gốm và địa chỉ nhận hàng để sắp xếp tuyến vận chuyển an toàn nhất. Chúng tôi sẽ liên hệ thông báo cước phí trong thời gian sớm nhất.": "HEDY needs to check the package size and delivery address to arrange the safest shipping route. We will contact you with the fee shortly.",
