    "[html]HEDY sẽ liên hệ xác nhận,<br /><em>chuẩn bị đơn hàng chu đáo.</em>": "HEDY will contact to confirm,<br /><em>and prepare your order carefully.</em>",
    "Đơn hàng của quý khách đã được ghi nhận thành công trên hệ thống. Vì các cổng thanh toán trực tuyến hiện đang trong quá trình xét duyệt và hoàn thiện tích hợp, chuyên viên HEDY sẽ trực tiếp gọi điện qua số": "Your order has been successfully recorded on the system. Because online payment gateways are currently under review and integration, a HEDY specialist will call you directly at",
    "để xác nhận chi tiết đơn và tư vấn phương thức thanh toán thuận tiện nhất (Chuyển khoản hoặc Tiền mặt khi nhận hàng).": "to confirm order details and advise on the most convenient payment method (Bank Transfer or Cash on Delivery).",
