    "Sau khi chuyển khoản thành công, quý khách vui lòng bấm nút thông báo và có thể đính kèm ảnh chụp màn hình giao dịch để HEDY đối chiếu và ưu tiên chuẩn bị đơn hàng sớm nhất.": "After a successful transfer, please click the notify button and optionally attach a screenshot of the transaction so HEDY can verify and prioritize preparing your order.",
