    "✓ Đã ghi nhận thông báo chuyển khoản của bạn.": "✓ Your transfer notification has been recorded.",
    "Hệ thống đã cập nhật trạng thái đơn sang “Chờ đối chiếu”. Chuyên viên HEDY sẽ kiểm tra tài khoản và xác nhận sớm nhất.": "The system has updated the order status to 'Awaiting reconciliation'. A HEDY specialist will check the account and confirm shortly.",
    "Sau khi chuyển tiền thành công, bấm “Tôi đã chuyển khoản” và tải ảnh biên lai để đơn được ưu tiên xử lý nhanh nhất.": "After a successful transfer, click 'I have transferred' and upload the receipt for priority processing.",
    "Lưu ý đối soát:": "Reconciliation note:",
    "Đơn hàng sẽ được nhân viên HEDY kiểm tra thực nhận trên tài khoản ngân hàng và cập nhật trước khi đóng gói xuất kho. Trạng thái chỉ chuyển sang “Đã thanh toán” khi kế toán hoàn tất đối soát số dư.": "The order will be checked by HEDY staff against the bank account and updated before shipping. The status only changes to 'Paid' when accounting completes balance reconciliation.",
    "HEDY sẽ chuẩn bị và giao kiện hàng đến bạn. Quý khách vui lòng kiểm tra kiện hàng và thanh toán đúng số tiền cho nhân viên giao hàng.": "HEDY will prepare and deliver the package to you. Please inspect the package and pay the exact amount to the delivery personnel.",
