    "Đơn hàng đã ghi nhận thành công, nhưng hệ thống email thông báo đang bận.": "Order recorded successfully, but the email notification system is busy.",
    "Mã đơn hàng vẫn hợp lệ. Vui lòng lưu lại mã đơn hàng trên màn hình; chuyên viên HEDY sẽ sớm liên hệ qua điện thoại.": "The order ID is valid. Please save the order ID on the screen; a HEDY specialist will contact you by phone shortly.",
