    "Phương thức thanh toán chỉ khả dụng sau khi HEDY kiểm tra kiện gốm và xác nhận cước vận chuyển chuyên biệt cùng tổng tiền cuối.": "Payment method is only available after HEDY inspects the ceramic package and confirms the specialized shipping fee along with the final total.",
