    "Chính sách an toàn HEDY: Đơn hàng trên 1.000.000₫ không áp dụng hình thức COD. Đơn hàng gốm sứ thủ công giá trị cao yêu cầu chuyển khoản trước để kích hoạt bảo hiểm kiện gốm an toàn và chuẩn bị vận chuyển riêng.": "HEDY Safety Policy: Orders over 1,000,000₫ do not apply COD. High-value handcrafted ceramic orders require prior bank transfer to activate safe ceramic package insurance and arrange specialized shipping.",
    "Đồng kiểm tra kiện gốm sứ cùng nhân viên giao hàng trước khi thanh toán.": "Co-inspect the ceramic package with the delivery personnel before payment.",
    "Không khả dụng đối với đơn hàng có giá trị trên 1.000.000₫. Quý khách vui lòng chọn Chuyển khoản ngân hàng.": "Not available for orders over 1,000,000₫. Please choose Bank Transfer.",
